<?php
require_once '../includes/auth.php'; requireActiveUser(); requireTenantContext(); requireModulePermission('network','view');
global $conn; $tenantId=(int)getCurrentTenantId(); $nodes=[];$links=[];
$q=$conn->prepare("SELECT * FROM network_map_nodes WHERE tenant_id=? ORDER BY id");if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$nodes[]=$r;$q->close();}
$q=$conn->prepare("SELECT l.*,s.label source_label,t.label target_label FROM network_map_links l LEFT JOIN network_map_nodes s ON s.id=l.source_node_id AND s.tenant_id=l.tenant_id LEFT JOIN network_map_nodes t ON t.id=l.target_node_id AND t.tenant_id=l.tenant_id WHERE l.tenant_id=? ORDER BY l.id");if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$links[]=$r;$q->close();}
$pageTitle='Network Map';require_once '../includes/header.php';?>
<div class="dashboard-card"><div class="page-header"><div><h2>Network Map</h2><p>Topology inventory for routers, sites, OLTs and network links.</p></div></div>
<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin-bottom:20px"><?php foreach($nodes as $n):?><div class="card" style="padding:16px"><strong><?=e($n['label'])?></strong><div><?=e($n['node_type'])?></div><small><?=e($n['status'])?></small></div><?php endforeach;?><?php if(!$nodes):?><div class="card" style="padding:16px">No topology nodes configured yet.</div><?php endif;?></div>
<div class="table-responsive"><table><thead><tr><th>Source</th><th>Target</th><th>Link</th><th>Bandwidth</th><th>Status</th></tr></thead><tbody><?php foreach($links as $l):?><tr><td><?=e($l['source_label']??$l['source_node_id'])?></td><td><?=e($l['target_label']??$l['target_node_id'])?></td><td><?=e($l['link_type'])?></td><td><?=e($l['bandwidth_mbps']??'—')?> Mbps</td><td><?=e($l['status'])?></td></tr><?php endforeach;?><?php if(!$links):?><tr><td colspan="5">No network links configured.</td></tr><?php endif;?></tbody></table></div></div><?php require_once '../includes/footer.php';?>